<?php
require_once 'config.php';
exigirLogin();
if (!temPerfil('admin')) { http_response_code(403); exit('Acesso restrito aos administradores.'); }
try {
    $metricas = [
        'usuarios' => (int) $pdo->query('SELECT COUNT(*) FROM usuarios WHERE ativo = TRUE')->fetchColumn(),
        'treinamentos' => (int) $pdo->query('SELECT COUNT(*) FROM treinamentos')->fetchColumn(),
        'aulas' => (int) $pdo->query('SELECT COUNT(*) FROM aulas')->fetchColumn(),
        'pendentes' => (int) $pdo->query("SELECT COUNT(*) FROM treinamentos WHERE status = 'rascunho'")->fetchColumn(),
        'materiais' => (int) $pdo->query('SELECT COUNT(*) FROM materiais')->fetchColumn(),
    ];
    $recentes = $pdo->query('SELECT titulo, status, criado_em FROM treinamentos ORDER BY criado_em DESC LIMIT 6')->fetchAll();
    $usuariosRecentes = $pdo->query('SELECT nome, perfil, criado_em FROM usuarios ORDER BY criado_em DESC LIMIT 4')->fetchAll();
} catch (Throwable $e) {
    error_log('TrainHub admin dashboard query failed: ' . $e->getMessage());
    $metricas = ['usuarios' => 0, 'treinamentos' => 0, 'aulas' => 0, 'pendentes' => 0, 'materiais' => 0]; $recentes = []; $usuariosRecentes = [];
}
